export const ICON_NAMES = Object.keys(P);

/** <Icon name="cube" size=${20} /> */
export function Icon({ name, size = 20, class: cls = '', title }) {
	const d = P[name] || P.info;
	return html`<svg class=${'p-icon ' + cls} width=${size} height=${size} viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden=${title ? undefined : 'true'} role=${title ? 'img' : undefined}>${title ? html`<title>${title}</title>` : null}<path d=${d} /></svg>`;
}
